namespace StickyNotes;
internal static class Visuals {
 public static void InstallResources(){if(SystemParameters.HighContrast)return;var style=(Style)System.Windows.Markup.XamlReader.Parse("<Style xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='ScrollBar'><Setter Property='Width' Value='7'/><Setter Property='Background' Value='Transparent'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ScrollBar'><Grid Background='Transparent'><Track x:Name='PART_Track' IsDirectionReversed='True'><Track.DecreaseRepeatButton><RepeatButton Command='ScrollBar.PageUpCommand' Opacity='0' Focusable='False'/></Track.DecreaseRepeatButton><Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType='Thumb'><Border Background='#608A8A94' CornerRadius='3' Margin='1,0'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Command='ScrollBar.PageDownCommand' Opacity='0' Focusable='False'/></Track.IncreaseRepeatButton></Track></Grid></ControlTemplate></Setter.Value></Setter></Style>");Application.Current.Resources[typeof(System.Windows.Controls.Primitives.ScrollBar)]=style;}
 public static Brush Brush(string s)=>new SolidColorBrush((Color)ColorConverter.ConvertFromString(s));
 public static bool Dark(string theme)=>theme=="Escuro"||(theme=="Sistema"&&(int)(Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize","AppsUseLightTheme",1)??1)==0);
 public static Button Icon(string glyph,string name,Action action){var b=new Button{ToolTip=name,Margin=new Thickness(2,0,2,0)};SuiteChrome.Apply(b,glyph);AutomationProperties.SetName(b,name);b.Click+=(_,_)=>action();return b;}
 public static Button TextButton(string text,Action action){bool dark=Dark(((NotesApp)Application.Current).Store?.Book.Theme??"Sistema");var b=new Button{Content=text,Padding=new Thickness(12,7,12,7),Margin=new Thickness(0,4,6,4),MinHeight=34,Foreground=SystemParameters.HighContrast?SystemColors.ControlTextBrush:Brush(dark?"#F2F2F5":"#29272F"),Background=SystemParameters.HighContrast?SystemColors.ControlBrush:Brush(dark?"#3B3E47":"#E4E6ED"),BorderBrush=Brush("#35808090"),BorderThickness=new Thickness(1)};b.Template=(ControlTemplate)System.Windows.Markup.XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Border x:Name='Surface' CornerRadius='6' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}'><ContentPresenter Margin='{TemplateBinding Padding}' HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Surface' Property='Opacity' Value='0.82'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='Surface' Property='Opacity' Value='0.65'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Surface' Property='BorderBrush' Value='{DynamicResource {x:Static SystemColors.HighlightBrushKey}}'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");AutomationProperties.SetName(b,text);b.Click+=(_,_)=>action();return b;}
 public static TextBox Input(string name,string text=""){var b=new TextBox{Text=text,Background=Brushes.Transparent,BorderThickness=new Thickness(0),Padding=new Thickness(0),VerticalContentAlignment=VerticalAlignment.Center};AutomationProperties.SetName(b,name);return b;}
 public static TextBlock Label(string s,double size=14)=>new(){Text=s,FontSize=size,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,3,0,3)};
 public static void Base(Window w,double width,double height){w.Width=width;w.Height=height;w.WindowStyle=WindowStyle.None;w.AllowsTransparency=true;w.Background=Brushes.Transparent;w.ShowInTaskbar=false;w.FontFamily=new FontFamily("Segoe UI Variable");w.FontSize=14;w.ResizeMode=ResizeMode.NoResize;}
 public static Border Surface(Window w,bool dark){var b=new Border{Margin=new Thickness(12),Padding=new Thickness(18),CornerRadius=new CornerRadius(12),BorderThickness=new Thickness(1),BorderBrush=Brush(dark?"#665F626A":"#507B7E86"),Background=Brush(dark?"#F524262B":"#F8F8F8FA"),Effect=new System.Windows.Media.Effects.DropShadowEffect{BlurRadius=18,ShadowDepth=3,Opacity=.22}};w.Foreground=Brush(dark?"#F5F5F7":"#252730");w.Content=b;return b;}
 public static void Reveal(Window w,FrameworkElement content){content.BeginAnimation(UIElement.OpacityProperty,null);content.RenderTransform=new TranslateTransform();if(!SystemParameters.ClientAreaAnimation||SystemParameters.HighContrast){content.Opacity=1;return;}var d=TimeSpan.FromMilliseconds(240);content.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(0,1,d));((TranslateTransform)content.RenderTransform).BeginAnimation(TranslateTransform.YProperty,new DoubleAnimation(10,0,d){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});}
 public static void Error(string message)=>MessageBox.Show(message,"Sticky Notes",MessageBoxButton.OK,MessageBoxImage.Warning);
}
